mapper.update:
UPDATE UNIT_TEST_ATTACHMENT SET
    IS_DELETED = 'Y'
WHERE FILE_ID = #{fileId}

UPDATE UNIT_TEST_ATTACHMENT SET
    IS_DELETED = 'Y'
WHERE TEST_CASE_ID = #{id}

mapper.select:
SELECT TEST_STATUS as testStatus, COUNT(*) as cnt FROM UNIT_TEST_CASE WHERE IS_DELETED = 'N'
AND TASK_ID = #{taskId}
AND ASSIGNEE = #{assignee}
GROUP BY TEST_STATUS ORDER BY TEST_STATUS

SELECT ASSIGNEE as assignee, COUNT(*) as totalCount, SUM(CASE WHEN TEST_STATUS = 'PEN' THEN 1 ELSE 0 END) as pendingCount, SUM(CASE WHEN TEST_STATUS = 'RUN' THEN 1 ELSE 0 END) as runningCount, SUM(CASE WHEN TEST_STATUS = 'SUC' THEN 1 ELSE 0 END) as successCount, SUM(CASE WHEN TEST_STATUS = 'FAI' THEN 1 ELSE 0 END) as failCount FROM UNIT_TEST_CASE WHERE IS_DELETED = 'N'
AND TASK_ID = #{taskId}
GROUP BY ASSIGNEE ORDER BY totalCount DESC, ASSIGNEE

SELECT PRIORITY as priority, COUNT(*) as cnt, CASE PRIORITY WHEN 'HIGH' THEN '높음' WHEN 'MEDIUM' THEN '보통' WHEN 'LOW' THEN '낮음' ELSE PRIORITY END as priorityName FROM UNIT_TEST_CASE WHERE IS_DELETED = 'N'
AND TASK_ID = #{taskId}
GROUP BY PRIORITY ORDER BY CASE PRIORITY WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 WHEN 'LOW' THEN 3 ELSE 4 END

SELECT TEST_TYPE as testType, COUNT(*) as cnt, CASE TEST_TYPE WHEN 'NORMAL' THEN '정상케이스' WHEN 'BOUNDARY' THEN '경계값' WHEN 'EXCEPTION' THEN '예외처리' WHEN 'PERFORMANCE' THEN '성능' ELSE TEST_TYPE END as testTypeName FROM UNIT_TEST_CASE WHERE IS_DELETED = 'N'
AND TASK_ID = #{taskId}
GROUP BY TEST_TYPE ORDER BY cnt DESC

SELECT UTC.ID as id, UTC.TEST_CASE_NAME as testCaseName, UTC.TEST_TARGET as testTarget, UTC.TEST_STATUS as testStatus, UTC.ASSIGNEE as assignee, DATE_FORMAT(UTC.EXECUTION_DATE, '%Y-%m-%d %H:%i') as executionDate, UTC.DURATION as duration, CASE UTC.TEST_STATUS WHEN 'PEN' THEN '대기' WHEN 'RUN' THEN '진행중' WHEN 'SUC' THEN '성공' WHEN 'FAI' THEN '실패' ELSE UTC.TEST_STATUS END as testStatusName FROM UNIT_TEST_CASE UTC WHERE UTC.IS_DELETED = 'N' AND UTC.EXECUTION_DATE IS NOT NULL
AND UTC.ASSIGNEE = #{assignee}
AND UTC.TASK_ID = #{taskId}
ORDER BY UTC.EXECUTION_DATE DESC LIMIT 0, 10
